    (1520101, 1520111, NULL, 'PM', N'NF ALPHA SA', NULL, NULL, 'C', 0),
    (1520102, 1520112, NULL, 'M.', N'NF BETA Paul', N'NF BETA', N'Paul', 'C', 0);
